agentflow-beta TB
  flow researcher["Researcher"]
    gather["Gather sources"]@{ shape: task }
  end
  flow writer["Writer"]
    draft["Compose draft"]@{ shape: task }
    check["Good enough?"]@{ shape: decision }
  end
